const rows = $input.all().map(item => item.json || {});

if (!rows.length || (rows.length === 1 && Object.keys(rows[0]).length === 0)) {
  throw new Error('User profile table returned no rows. Select the correct Data Table in Read User Profile.');
}

const profile = {};
const categories = {};

for (const row of rows) {
  const key = String(row.key ?? '').trim();
  if (!key) continue;

  const value = row.value ?? '';
  const category = String(row.category ?? 'uncategorized').trim();

  profile[key] = value;

  if (!categories[category]) {
    categories[category] = {};
  }

  categories[category][key] = value;
}

const context = {
  generatedAt: new Date().toISOString(),
  timezone: profile.timezone || 'Asia/Dubai',
  identity: {
    name: profile.name || 'Savaş',
    language: profile.language || 'Turkish'
  },
  locations: {
    home: profile.home_location || 'Palm Jumeirah, Dubai',
    work: profile.work_location || 'Abu Dhabi'
  },
  schedule: {
    mondayTuesday: profile.monday_tuesday || '',
    wednesdayThursday: profile.wednesday_thursday || '',
    weekend: profile.weekend || ''
  },
  goals: {
    fitness: profile.fitness_goals || '',
    social: profile.social_goals || '',
    style: profile.style_goals || '',
    dating: profile.dating_goals || '',
    personalGrowth: profile.personal_growth || '',
    career: profile.career || ''
  },
  preferences: {
    venues: profile.preferred_venues || '',
    memberships: profile.memberships || ''
  },
  rawProfile: profile,
  categories
};

const promptContext = [
  `Name: ${context.identity.name}`,
  `Language: ${context.identity.language}`,
  `Timezone: ${context.timezone}`,
  `Home: ${context.locations.home}`,
  `Work: ${context.locations.work}`,
  `Monday/Tuesday: ${context.schedule.mondayTuesday}`,
  `Wednesday/Thursday: ${context.schedule.wednesdayThursday}`,
  `Weekend: ${context.schedule.weekend}`,
  `Fitness goals: ${context.goals.fitness}`,
  `Social goals: ${context.goals.social}`,
  `Style goals: ${context.goals.style}`,
  `Dating goals: ${context.goals.dating}`,
  `Personal growth: ${context.goals.personalGrowth}`,
  `Career: ${context.goals.career}`,
  `Preferred venues: ${context.preferences.venues}`,
  `Memberships: ${context.preferences.memberships}`
].filter(line => !line.endsWith(': ')).join('\n');

return [{
  json: {
    success: true,
    userContext: context,
    promptContext,
    profileRowCount: rows.length
  }
}];
